param([string]$SettingsFile)
$ErrorActionPreference='Stop'
function Exe([string]$value){if(-not $value){return $null};$value=[Environment]::ExpandEnvironmentVariables($value.Trim());if($value -match '"([^"]+\.exe)"'){$value=$Matches[1]}elseif($value -match '^(.+?\.exe)(?:,|\s+/|$)'){$value=$Matches[1]};if(Test-Path -LiteralPath $value -PathType Leaf){return [IO.Path]::GetFullPath($value)};return $null}
if($SettingsFile -and (Test-Path -LiteralPath $SettingsFile)){try{$old=Get-Content -LiteralPath $SettingsFile -Raw -Encoding UTF8|ConvertFrom-Json;$engine=if($old.spreadsheetEngine){$old.spreadsheetEngine}elseif(Exe $old.wpsExe){'wps'}else{'excel'};$office=if($engine -eq 'excel'){Exe $old.excelExe}elseif($engine -eq 'wps'){Exe $old.wpsExe}else{$null};if((Exe $old.dmExe)-and(Exe $old.dqExe)-and $office){[ordered]@{dmExe=$old.dmExe;dqExe=$old.dqExe;wpsExe=$old.wpsExe;excelExe=$old.excelExe;spreadsheetEngine=$engine;cached=$true}|ConvertTo-Json -Compress;return}}catch{}}
$dm=Exe (Join-Path $env:LOCALAPPDATA 'Innodealing\DM-Native\launcher.exe');$dq=$null;$wps=$null;$excel=$null
foreach($base in @($env:ProgramFiles,${env:ProgramFiles(x86)})){if($base){$folder=Join-Path $base 'cbpc';if(Test-Path -LiteralPath $folder){$found=Get-ChildItem -LiteralPath $folder -Filter '*.exe'|Where-Object {$_.Name -notmatch '^Uninstall' -and $_.Name -match 'DQ'}|Select-Object -First 1;if($found){$dq=$found.FullName}}}}
foreach($view in @([Microsoft.Win32.RegistryView]::Registry64,[Microsoft.Win32.RegistryView]::Registry32)){
 try{$key=[Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::ClassesRoot,$view);foreach($id in @('ket.Application','Excel.Application')){$prog=$key.OpenSubKey($id+'\CLSID');if($prog){$cls=$prog.GetValue('');$server=$key.OpenSubKey('CLSID\'+$cls+'\LocalServer32');if($server){$candidate=Exe ([string]$server.GetValue(''));if($candidate){if($id -eq 'ket.Application'){$wps=$candidate}elseif([IO.Path]::GetFileName($candidate) -ieq 'EXCEL.EXE'){$excel=$candidate}};$server.Close()};$prog.Close()}};$key.Close()}catch{}
}
foreach($location in @('HKCU:\Software\Microsoft\Windows\CurrentVersion\App Paths\excel.exe','HKLM:\Software\Microsoft\Windows\CurrentVersion\App Paths\excel.exe','HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\App Paths\excel.exe')){if(-not $excel -and (Test-Path $location)){$candidate=Exe ((Get-Item $location).GetValue(''));if($candidate -and [IO.Path]::GetFileName($candidate) -ieq 'EXCEL.EXE'){$excel=$candidate}}}
if(-not $excel){foreach($base in @($env:ProgramFiles,${env:ProgramFiles(x86)})){if($base){foreach($relative in @('Microsoft Office\root\Office*\EXCEL.EXE','Microsoft Office\Office*\EXCEL.EXE')){$candidate=Get-ChildItem -Path (Join-Path $base $relative) -File -ErrorAction SilentlyContinue|Select-Object -First 1;if($candidate){$excel=$candidate.FullName;break}}}}}
if(-not $wps){$p=Get-Process -Name et -ErrorAction SilentlyContinue|Select-Object -First 1;if($p){$wps=Exe $p.Path}}
foreach($pattern in @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*')){
 foreach($item in @(Get-ItemProperty $pattern -ErrorAction SilentlyContinue)){
  $kind=if($item.DisplayName -match 'DM-Native|Innodealing'){'dm'}elseif($item.DisplayName -match 'DQ'){'dq'}elseif($item.DisplayName -match 'WPS'){'wps'}else{''};if(-not $kind){continue}
  $candidate=Exe ([string]$item.DisplayIcon);if($kind -eq 'dm' -and -not $dm -and $candidate){$launcher=Exe (Join-Path (Split-Path -Parent $candidate) 'launcher.exe');$dm=if($launcher){$launcher}else{$candidate}}
  if($kind -eq 'dq' -and -not $dq -and $candidate){$dq=$candidate}
 }
}
if(-not $dm -or -not $dq){$shell=New-Object -ComObject WScript.Shell;foreach($start in @([Environment]::GetFolderPath('StartMenu'),[Environment]::GetFolderPath('CommonStartMenu'))){foreach($link in @(Get-ChildItem -LiteralPath $start -Filter '*.lnk' -Recurse -ErrorAction SilentlyContinue|Where-Object {$_.Name -match 'DM|DQ'})){$target=Exe $shell.CreateShortcut($link.FullName).TargetPath;if($target){if(-not $dm -and $link.Name -match 'DM'){$dm=$target};if(-not $dq -and $link.Name -match 'DQ'){$dq=$target}}}}}
if($wps -and [IO.Path]::GetFileName($wps) -ne 'et.exe'){$candidate=Exe (Join-Path (Split-Path -Parent $wps) 'et.exe');if($candidate){$wps=$candidate}else{$wps=$null}}
if(-not $wps){foreach($base in @($env:LOCALAPPDATA,$env:ProgramFiles,${env:ProgramFiles(x86)})){if($base){$found=Get-ChildItem -Path (Join-Path $base 'Kingsoft\WPS Office\*\office6\et.exe') -ErrorAction SilentlyContinue|Select-Object -First 1;if($found){$wps=$found.FullName;break}}}}
$selected=if($old.spreadsheetEngine){$old.spreadsheetEngine}elseif($wps){'wps'}elseif($excel){'excel'}else{'wps'}
[ordered]@{dmExe=$dm;dqExe=$dq;wpsExe=$wps;excelExe=$excel;spreadsheetEngine=$selected;cached=$false}|ConvertTo-Json -Compress
